from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(9,'decimaux','Les décimaux jusqu’aux millièmes','2 · Fractions et nombres décimaux',
'Millièmes · Comparaisons · Encadrements · Arrondis',
['Lire, décomposer et écrire des décimaux jusqu’aux millièmes.','Comparer, encadrer, intercaler des décimaux.','Donner la partie entière et l’arrondi à l’entier.'],
['Dixièmes et centièmes du CM1.'],[
page(1,'Le rang des millièmes',
bloc('definition',r'Partager un centième en 10 donne des millièmes : $\frac1{1\,000}$. Une unité vaut 10 dixièmes, 100 centièmes ou $1\,000$ millièmes. L’écriture $4{,}375$ code $4+\frac3{10}+\frac7{100}+\frac5{1\,000}$.')+
tableau(['Nombre','unités','dixièmes','centièmes','millièmes'],[[r'$4{,}375$','4','3','7','5'],[r'$6{,}04$','6','0','4',''],[r'$0{,}208$','0','2','0','8']]),
bloc('exemple',r'$\frac{2\,375}{1\,000}=2+\frac{375}{1\,000}=2{,}375$. Et $0{,}208$ se lit « 208 millièmes » : $\frac{208}{1\,000}$, soit 2 dixièmes et 8 millièmes, sans centième.'),
bloc('savoirfaire',r'Les millièmes mesurent finement : $1$ m $=1\,000$ mm, donc 1 mm $=0{,}001$ m ; une masse de 1 g vaut $0{,}001$ kg. Lire « 3 m et 45 mm » : $3{,}045$ m.','Des millièmes bien réels')),
page(2,'Comparer et arrondir',
bloc('propriete',r'Comparer rang par rang, après la partie entière : $6{,}4>6{,}385$, car 4 dixièmes dépassent 3 dixièmes ; le nombre de chiffres ne décide pas. Compléter par des zéros aide : $6{,}400$ contre $6{,}385$.'),
bloc('savoirfaire',r'Intercaler est toujours possible : entre $5{,}27$ et $5{,}28$, penser en millièmes : $5{,}275$ convient. Encadrer au dixième : $8{,}236$ est entre $8{,}2$ et $8{,}3$.','Encadrer et intercaler'),
bloc('exemple',r'Arrondi à l’entier : regarder les dixièmes. $7{,}493\to7$ ; $7{,}51\to8$ ; $12{,}5\to13$ par convention à mi-chemin. Sur la demi-droite, l’arrondi est l’entier le plus proche.'),
bloc('attention',r'$0{,}5$ ; $0{,}50$ ; $0{,}500$ désignent le même nombre : les zéros finaux après la virgule ne changent rien. En revanche $0{,}05$ et $0{,}005$ sont dix fois plus petits l’un que l’autre.'))
],[
E('Lire les rangs',r'Dans $4{,}375$, donner le chiffre des centièmes et le chiffre des millièmes, puis décomposer le nombre.',r'Centièmes : $\res7$ ; millièmes : $\res5$. Décomposition : $\res{4+\frac3{10}+\frac7{100}+\frac5{1\,000}}$.','Compter les rangs après la virgule.','assert Rational("4.375")==4+Rational(3,10)+Rational(7,100)+Rational(5,1000)'),
E('Des fractions aux virgules',r'Écrire avec une virgule : $\frac{2\,375}{1\,000}$ ; $\frac{208}{1\,000}$ ; $\frac{45}{1\,000}$.',r'$\res{2{,}375}$ ; $\res{0{,}208}$ ; $\res{0{,}045}$. Les zéros tiennent les rangs vides.','Extraire la partie entière puis coder.','assert Rational(2375,1000)==Rational("2.375") and Rational(208,1000)==Rational(".208") and Rational(45,1000)==Rational(".045")'),
E('Des virgules aux fractions',r'Décomposer $6{,}04$ et $0{,}208$ avec des fractions décimales.',r'$6{,}04=\res{6+\frac4{100}}$ : aucun dixième. $0{,}208=\res{\frac2{10}+\frac8{1\,000}}$ : aucun centième.','Lire chaque chiffre avec son rang.','assert Rational("6.04")==6+Rational(4,100) and Rational(".208")==Rational(2,10)+Rational(8,1000)'),
E('Mètres et millimètres',r'Écrire en mètres : 3 m et 45 mm ; 2 m et 7 mm ; 605 mm.',r'1 mm $=0{,}001$ m : $\res{3{,}045}$ m ; $\res{2{,}007}$ m ; $\res{0{,}605}$ m.','Placer les millimètres au rang des millièmes.','assert 3+Rational(45,1000)==Rational("3.045") and 2+Rational(7,1000)==Rational("2.007") and Rational(605,1000)==Rational(".605")'),
E('Le piège des longueurs d’écriture',r'Comparer $6{,}4$ et $6{,}385$, puis $0{,}72$ et $0{,}702$.',r'$6{,}400>6{,}385$ : $\res{6{,}4>6{,}385}$. Et $0{,}720>0{,}702$ : $\res{0{,}72>0{,}702}$. Plus de chiffres ne signifie pas plus grand.','Compléter avec des zéros pour aligner les rangs.','assert Rational("6.4")>Rational("6.385") and Rational(".72")>Rational(".702")'),
E('Ranger',r'Ranger dans l’ordre croissant : $3{,}205$ ; $3{,}25$ ; $3{,}052$ ; $3{,}5$ ; $3{,}055$.',r'En millièmes : $3\,052$ ; $3\,055$ ; $3\,205$ ; $3\,250$ ; $3\,500$. Donc $\res{3{,}052<3{,}055<3{,}205<3{,}25<3{,}5}$.','Penser chaque nombre en millièmes.','assert Rational("3.052")<Rational("3.055")<Rational("3.205")<Rational("3.25")<Rational("3.5")'),
E('Encadrer au dixième',r'Encadrer $8{,}236$ entre deux dixièmes consécutifs, puis entre deux centièmes consécutifs.',r'$\res{8{,}2<8{,}236<8{,}3}$ et $\res{8{,}23<8{,}236<8{,}24}$.','Geler les rangs avant celui demandé.','assert Rational("8.2")<Rational("8.236")<Rational("8.3") and Rational("8.23")<Rational("8.236")<Rational("8.24")'),
E('Intercaler',r'Donner un nombre strictement compris entre $5{,}27$ et $5{,}28$, puis entre $0{,}999$ et 1.',r'En millièmes : $\res{5{,}275}$ convient. Entre $0{,}999$ et 1, penser en dix-millièmes : $\res{0{,}9995}$ convient. Entre deux décimaux distincts, il y a toujours de la place.','Ajouter un rang décimal.','assert Rational("5.27")<Rational("5.275")<Rational("5.28") and Rational(".999")<Rational(".9995")<1'),
E('Arrondir',r'Donner l’arrondi à l’entier de $7{,}493$ ; $7{,}51$ ; $12{,}5$.',r'$7{,}493\to\res7$ (4 dixièmes) ; $7{,}51\to\res8$ ; $12{,}5\to\res{13}$, à mi-chemin on choisit l’entier supérieur.','Regarder le chiffre des dixièmes.','assert abs(Rational("7.493")-7)<abs(Rational("7.493")-8) and abs(Rational("7.51")-8)<abs(Rational("7.51")-7) and Rational("12.5")-12==13-Rational("12.5")'),
E('Sur la demi-droite',r'La demi-droite est graduée de $0{,}01$ en $0{,}01$. Lire A et B, puis placer $C(4{,}235)$.',r'$\res{A(4{,}21)}$ et $\res{B(4{,}27)}$. C se place au milieu du pas entre $4{,}23$ et $4{,}24$ ; en vert au corrigé.','Lire le pas avant les positions.','assert Rational("4.23")<Rational("4.235")<Rational("4.24")',figure='dec-10'),
E('Les performances',r'Au saut en longueur, Aya saute $3{,}205$ m, Lou $3{,}25$ m et Mia $3{,}209$ m. Donner le podium, puis l’écart entre les deux premières.',r'$3{,}250>3{,}209>3{,}205$ : $\res{\text{Lou, puis Mia, puis Aya}}$. Écart de tête : $3{,}25-3{,}209=\res{0{,}041}$ m, soit 41 millimètres.','Comparer en millièmes de mètre.','assert Rational("3.25")>Rational("3.209")>Rational("3.205") and Rational("3.25")-Rational("3.209")==Rational(".041")'),
E('Le même nombre ?',r'Parmi ces écritures, regrouper celles qui désignent le même nombre : $0{,}5$ ; $0{,}050$ ; $0{,}500$ ; $\frac5{10}$ ; $\frac{50}{1\,000}$.',r'$0{,}5=0{,}500=\frac5{10}$ forment un groupe ; $0{,}050=\frac{50}{1\,000}$ l’autre : dix fois plus petit. Les zéros finaux ne changent rien, les zéros intercalés si.','Comparer rang par rang, pas à l’œil.','assert Rational(".5")==Rational(".500")==Rational(5,10) and Rational(".050")==Rational(50,1000) and Rational(".5")!=Rational(".05")'),
E('La bonne précision',r'Un robot découpe des pièces de $0{,}125$ m. Exprimer cette longueur en millimètres, puis dire combien de pièces entières il découpe dans une barre de 1 m.',r'$0{,}125$ m $=\res{125}$ mm. Dans $1\,000$ mm : $125\times8=1\,000$, soit $\res8$ pièces exactement.','Convertir en millimètres pour compter.','assert Rational(".125")*1000==125 and 125*8==1000'),
E('L’arrondi trompeur',r'Deux nombres différents peuvent-ils avoir le même arrondi à l’entier ? Donner un exemple avec des millièmes, puis expliquer pourquoi l’arrondi ne suffit pas pour comparer.',r'$\res{\text{Oui}}$ : $7{,}499$ et $6{,}502$ s’arrondissent tous deux à 7, pourtant $7{,}499>6{,}502$. L’arrondi estime, mais la comparaison exige les valeurs exactes.','Chercher deux nombres proches d’un même entier.','assert abs(Rational("7.499")-7)<Rational(1,2) and abs(Rational("6.502")-7)<Rational(1,2) and Rational("7.499")>Rational("6.502")'),
E('Zéro virgule neuf cent quatre-vingt-dix-neuf',r'Nino affirme : « $0{,}999$ est plus grand que $0{,}99$ car il a plus de chiffres ; et il est plus grand que 1 car 999 est grand. » Démêler le vrai du faux.',r'$0{,}999>0{,}99$ est $\res{\text{vrai}}$ : 999 millièmes contre 990. Mais $0{,}999<1$ : il manque un millième. « Plus de chiffres » n’est jamais l’argument : seuls les rangs comptent.','Compléter les écritures au même rang.','assert Rational(".999")>Rational(".99") and Rational(".999")<1 and 1-Rational(".999")==Rational(1,1000)')
],reperes=['Millièmes et décompositions','Comparer et ranger','Encadrer, intercaler','Arrondis et problèmes'],deco='calcul')

chapitre(10,'calculs-decimaux','Calculer avec les décimaux','2 · Fractions et nombres décimaux',
'Sommes · Produits · Divisions · Rangs',
['Additionner, soustraire et multiplier des décimaux par un entier.','Multiplier et diviser par 10, 100, 1 000.','Calculer doubles, moitiés et quotients décimaux utiles.'],
['Opérations posées et rangs jusqu’aux millièmes.'],[
page(1,'Sommes, différences, produits',
bloc('savoirfaire',r'Virgules alignées, rangs complétés : $12{,}7+3{,}85=16{,}55$ et $20-4{,}35=15{,}65$. L’estimation encadre : $12{,}7+3{,}85$ est proche de $13+4=17$.','Aligner et estimer'),
bloc('exemple',r'$6{,}38\times7$ : calculer $638\times7=4\,466$, puis replacer deux chiffres après la virgule : $44{,}66$. Estimation : $6{,}4\times7\approx45$.'),
bloc('propriete',r'Multiplier par 10, 100 ou $1\,000$ fait monter les chiffres de 1, 2 ou 3 rangs : $3{,}456\times100=345{,}6$. Diviser fait descendre : $47{,}2:100=0{,}472$.'),
bloc('savoirfaire',r'Doubles et moitiés : le double de $3{,}45$ est $6{,}9$ ; la moitié de $7{,}3$ est $3{,}65$ (la moitié de 73 dixièmes fait 36 dixièmes et demi, soit 365 centièmes). Multiplier par 5 : multiplier par 10 puis prendre la moitié ; par 50 : par 100 puis la moitié.','Procédures de tête')),
page(2,'Diviser un décimal',
bloc('exemple',r'$25{,}5:3$ : 25 unités donnent 8, reste 1 ; 15 dixièmes donnent 5 dixièmes. Quotient : $8{,}5$. Contrôle : $8{,}5\times3=25{,}5$.'),
bloc('savoirfaire',r'Diviser par 4 : deux moitiés successives. $18:4$ : moitié 9, moitié $4{,}5$. Diviser par 8 : trois moitiés. Ces chemins évitent de poser l’opération.','Diviser par 4 ou par 8'),
bloc('propriete',r'Le quotient peut demander des rangs supplémentaires : $7{,}3:5$ : 7 unités donnent 1 ; 23 dixièmes donnent 4 ; reste 3 dixièmes, soit 30 centièmes ; 30 centièmes donnent 6. Quotient exact : $1{,}46$.'),
bloc('attention',r'Multiplier un nombre par un décimal plus petit que 1 le diminue, et diviser par 10 le rapetisse : les automatismes « multiplier agrandit toujours » cessent d’être vrais hors des entiers. Les rangs, eux, ne mentent jamais.'))
],[
E('Somme et différence',r'Poser et calculer $12{,}7+3{,}85$, puis $20-4{,}35$.',r'$12{,}70+3{,}85=\res{16{,}55}$ ; $20{,}00-4{,}35=\res{15{,}65}$ ; contrôle : $15{,}65+4{,}35=20$.','Aligner les virgules, compléter les rangs.','assert Rational("12.7")+Rational("3.85")==Rational("16.55") and 20-Rational("4.35")==Rational("15.65")'),
E('Un produit posé',r'Poser et calculer $6{,}38\times7$.',r'$638\times7=4\,466$, donc $6{,}38\times7=\res{44{,}66}$. Estimation : $6{,}4\times7\approx45$.','Compter les chiffres après la virgule.','assert Rational("6.38")*7==Rational("44.66")'),
E('Par 10, 100, 1 000',r'Calculer $3{,}456\times100$ ; $0{,}07\times1\,000$ ; $47{,}2:100$ ; $5:1\,000$.',r'$\res{345{,}6}$ ; $\res{70}$ ; $\res{0{,}472}$ ; $\res{0{,}005}$.','Déplacer les chiffres de rangs, pas « la virgule magique ».','assert Rational("3.456")*100==Rational("345.6") and Rational(".07")*1000==70 and Rational("47.2")/100==Rational(".472") and Rational(5,1000)==Rational(".005")'),
E('Doubles et moitiés',r'Donner le double de $3{,}45$ ; la moitié de $7{,}3$ ; la moitié de $0{,}9$.',r'Double : $\res{6{,}9}$. Moitié de $7{,}3$ : $\res{3{,}65}$. Moitié de $0{,}9$ : $\res{0{,}45}$.','Travailler en dixièmes ou centièmes.','assert Rational("3.45")*2==Rational("6.9") and Rational("7.3")/2==Rational("3.65") and Rational(".9")/2==Rational(".45")'),
E('Multiplier par 5 et par 50',r'Calculer de tête $4{,}6\times5$, puis $2{,}4\times50$.',r'$4{,}6\times10=46$, moitié : $\res{23}$. $2{,}4\times100=240$, moitié : $\res{120}$.','Passer par 10 ou 100 puis prendre la moitié.','assert Rational("4.6")*5==23 and Rational("2.4")*50==120'),
E('Division en ligne',r'Calculer $25{,}5:3$, puis contrôler par la multiplication.',r'25 unités : 8, reste 1 ; 15 dixièmes : 5. Quotient $\res{8{,}5}$ ; contrôle : $8{,}5\times3=25{,}5$.','Passer le reste au rang suivant.','assert Rational("25.5")/3==Rational("8.5")'),
E('Diviser par 4 et par 8',r'Calculer $18:4$ et $18:8$ par moitiés successives.',r'$18\to9\to\res{4{,}5}$ : deux moitiés pour $:4$. Une moitié de plus : $18:8=\res{2{,}25}$.','Prendre la moitié deux ou trois fois.','assert Rational(18,4)==Rational("4.5") and Rational(18,8)==Rational("2.25")'),
E('Le quotient qui s’allonge',r'Calculer le quotient exact de $7{,}3:5$.',r'7 unités : 1 ; 23 dixièmes : 4, reste 3 ; 30 centièmes : 6. Quotient $\res{1{,}46}$ ; contrôle : $1{,}46\times5=7{,}3$.','Poursuivre jusqu’au reste nul.','assert Rational("7.3")/5==Rational("1.46")'),
E('Compléments et regroupements',r'Calculer $4{,}35+2{,}8+0{,}65$ en regroupant astucieusement, puis compléter : $6{,}25+\square=10$.',r'$4{,}35+0{,}65=5$, puis $5+2{,}8=\res{7{,}8}$. Complément : $\res{3{,}75}$.','Chercher les paires qui font un compte rond.','assert Rational("4.35")+Rational("2.8")+Rational(".65")==Rational("7.8") and Rational("6.25")+Rational("3.75")==10'),
E('L’estimation qui sauve',r'Sans poser le calcul, choisir le bon résultat de $19{,}8\times6$ parmi : $1{,}188$ ; $11{,}88$ ; $118{,}8$ ; $1\,188$. Justifier.',r'$19{,}8$ est proche de 20 et $20\times6=120$ : le seul résultat vraisemblable est $\res{118{,}8}$.','Encadrer par un produit d’entiers ronds.','assert Rational("19.8")*6==Rational("118.8")'),
E('Les courses du club',r'Le club achète 6 ballons à $12{,}45$ euros l’un et 3 pompes à $4{,}20$ euros l’une.'+Q(r'Calculer la dépense totale.',r'Le club paie avec 90 euros. Combien lui rend-on ?'),r'Ballons : $12{,}45\times6=74{,}70$ euros ; pompes : $4{,}20\times3=12{,}60$ euros ; total $\res{87{,}30}$ euros. Monnaie : $90-87{,}30=\res{2{,}70}$ euros.','Calculer chaque produit avant la somme.','assert Rational("12.45")*6==Rational("74.70") and Rational("4.20")*3==Rational("12.60") and Rational("74.70")+Rational("12.60")==Rational("87.30") and 90-Rational("87.30")==Rational("2.70")'),
E('Le carrelage du couloir',r'Un couloir mesure $7{,}2$ m. On le carrelle avec des dalles de $0{,}4$ m posées bout à bout. Combien de dalles faut-il sur la longueur ?',r'En décimètres : $72:4=\res{18}$ dalles. Changer d’unité remplace la division décimale par une division entière.','Convertir pour diviser des entiers.','assert Rational("7.2")/Rational(".4")==18 and 72//4==18'),
E('Le partage du week-end',r'Trois amis se partagent équitablement $25{,}5$ euros gagnés au vide-grenier, puis chacun dépense $5{,}90$ euros. Combien reste-t-il à chacun ?',r'Part : $25{,}5:3=\res{8{,}5}$ euros. Après dépense : $8{,}5-5{,}90=\res{2{,}60}$ euros chacun.','Partager avant de soustraire.','assert Rational("25.5")/3==Rational("8.5") and Rational("8.5")-Rational("5.90")==Rational("2.60")'),
E('La moyenne du relais',r'Quatre coureurs parcourent ensemble $10{,}8$ km en se partageant également la distance. Quelle distance parcourt chacun ? L’un d’eux ne court que $2{,}5$ km : qui doit compenser, et de combien ?',r'Part égale : $10{,}8:4=\res{2{,}7}$ km. Le coureur fait $2{,}7-2{,}5=0{,}2$ km de moins : un autre devra courir $\res{0{,}2}$ km de plus, soit $2{,}9$ km.','Comparer chaque part à la part égale.','assert Rational("10.8")/4==Rational("2.7") and Rational("2.7")-Rational("2.5")==Rational(".2") and Rational("2.7")+Rational(".2")==Rational("2.9")'),
E('Multiplier rapetisse ?',r'Vrai ou faux : « Multiplier un nombre par 10 l’agrandit toujours » ; « Diviser un nombre par 10 l’agrandit parfois ». Justifier avec $0{,}3$.',r'$0{,}3\times10=3>0{,}3$ : la première est $\res{\text{vraie}}$ pour les nombres positifs non nuls. $0{,}3:10=0{,}03<0{,}3$ : diviser par 10 rapetisse toujours un nombre positif : la seconde est $\res{\text{fausse}}$.','Tester sur un décimal plus petit que 1.','assert Rational(".3")*10==3 and Rational(".3")/10==Rational(".03") and Rational(".03")<Rational(".3")<3')
],reperes=['Poser avec les décimaux','Rangs : par 10, 100, 1 000','Doubles, moitiés, divisions','Problèmes de la vie courante'],deco='calcul')
